{
  "@context": {
    "@language": "en",
    "@vocab": "https://schema.org/",
    "cr": "http://mlcommons.org/croissant/",
    "dct": "http://purl.org/dc/terms/",
    "sc": "https://schema.org/"
  },
  "@type": "cr:TaskProblem",
  "conformsTo": "http://mlcommons.org/croissant/1.0",
  "@id": "privacy-llm-task",
  "name": "Privacy in Large Language Models (LLM-PBE)",
  "description": "A competition to identify and mitigate privacy vulnerabilities in large language models, focusing on sensitive information leakage and defense mechanisms.",
  "paper_id": "[FILL IN THE BLANK: original paper identifier]",

  "cr:input": [
    {
      "@type": "cr:FileObject",
      "name": "input_data",
      "description": "Input data consists of a single column 'id' representing sample identifiers. Example values: sample_000, sample_001, sample_002.",
      "encodingFormat": "text/csv",
      "contentUrl": "[FILL IN THE BLANK: dataset source URL]"
    }
  ],

  "cr:output": {
    "name": "predictions",
    "description": "Predictions consist of two columns: 'id' (sample identifier) and 'pred' (binary classification output, either 0 or 1). Example values: sample_000 -> 1, sample_001 -> 0.",
    "cr:schema": {
      "@type": "cr:RecordSet",
      "name": "prediction_schema",
      "field": [
        {
          "@type": "cr:Field",
          "name": "id",
          "dataType": "sc:Text",
          "description": "Sample identifier. Example values: sample_000, sample_001."
        },
        {
          "@type": "cr:Field",
          "name": "pred",
          "dataType": "sc:Integer",
          "description": "Binary prediction output (0 or 1). Example values: 1, 0."
        }
      ]
    }
  },

  "cr:implementation": {
    "cr:environment": {
      "language": "Python",
      "packages": ["numpy", "pandas", "scipy", "sklearn"]
    },
    "entryPoint": "solution.py",
    "interface": "predict(input_dir, output_dir)"
  },

  "cr:evaluation": {
    "primaryMetric": "Attack Accuracy",
    "metrics": [
      "Attack Accuracy",
      "Efficiency",
      "Defense Effectiveness",
      "Model Effectiveness",
      "Statistical Significance (t-test p-value)",
      "Statistical Significance (ANOVA p-value)"
    ],
    "higherIsBetter": true,
    "notes": "Metrics include accuracy for attack and defense, efficiency (e.g., computational overhead or token usage), and statistical significance tests (t-test and ANOVA)."
  },

  "cr:execution": {
    "runtimeLimitSec": 600,
    "memoryLimitMb": 4096,
    "allowedExternalData": "unknown"
  },

  "open_questions": [
    "The exact paper identifier is missing.",
    "Dataset source URL is not provided."
  ],

  "fill_in_the_blank": [
    "paper_id - reason it could not be determined from the paper",
    "cr:input[0].contentUrl - reason it could not be determined from the paper"
  ]
}
